"use client";

import React from "react";
import Image from "next/image";
import PropTypes from "prop-types";

const SensorCard = ({ icon, value, title, bgColorClass, iconColorClass, unit }) => {
  return (
    <div className={`border-2 hover:shadow-lg border-gray-200 ${bgColorClass || 'bg-gray-100'} px-4 py-6 rounded-2xl transition-all duration-300`}>
      <div className="flex items-center justify-between px-6">
        <div className={`${iconColorClass || 'bg-[#D9D9D9]'} rounded-full overflow-hidden p-3`}>
          <Image
            src={icon}
            alt={`${title} Icon`}
            width={38}
            height={38}
            priority={true}
          />
        </div>

        <div className="text-4xl font-poppins-bold text-[#2E59BE]">
          {value} <span className="text-2xl">{unit}</span>
        </div>
      </div>
      <h2 className="pt-4 title-font font-poppins-semi-bold text-lg text-[#2E59BE]">
        {title}
      </h2>
    </div>
  );
};

SensorCard.propTypes = {
  icon: PropTypes.object.isRequired,
  value: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
  title: PropTypes.string.isRequired,
  bgColorClass: PropTypes.string,
  iconColorClass: PropTypes.string,
  unit: PropTypes.string.isRequired
};

export default SensorCard;
